import {professionLabel} from './profession.js';
import {forecastStamp} from './forecast-receipt.js';
import {zoneOutline} from './map-outline.js';
import {esc,weatherName,valueText} from './weather-tools.js';
export const LIVING_FEATURES={enabled:true,video:false,vocali:false,meteoClans:false,legacyCommunity:true};
export const reportTitle=r=>r.phenomenon||((Number.isInteger(r.level)&&r.level>=0&&r.level<=4)?['Asciutto','Qualche goccia','Pioviggina','Piove','Diluvio'][r.level]:null)||({rain:'Pioggia',sun:'Sereno',dry:'Asciutto',wind:'Vento',snow:'Neve',hail:'Grandine',cloud:'Nuvoloso',alert:'Allagamento'}[r.kind]||'Il cielo della zona');
const $=s=>document.querySelector(s),motion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
export const distanceKm=(a,b)=>{const d=Math.PI/180;return 12742*Math.asin(Math.min(1,Math.sqrt(Math.sin((b.latitude-a.latitude)*d/2)**2+Math.cos(a.latitude*d)*Math.cos(b.latitude*d)*Math.sin((b.longitude-a.longitude)*d/2)**2)))};
export const reportEmoji=r=>({rain:'🌧',hail:'🧊',snow:'❄️',wind:'💨',flood:'🌊',alert:'🌊',sun:'☀️',dry:'☀️',cloud:'☁️'}[r.kind]||'🌤');
export const activeReports=(rows,now=Date.now())=>(rows||[]).filter(r=>r.created<=now&&r.created>now-7200000&&r.expires>now&&Number.isFinite(r.latitude)&&Number.isFinite(r.longitude));
let libPromise;
const introSeen=()=>{try{return sessionStorage.getItem('meteo-map-intro')==='1'}catch{return false}};
const markIntro=()=>{try{sessionStorage.setItem('meteo-map-intro','1')}catch{}};
export function library(){
 if(window.maplibregl)return Promise.resolve(window.maplibregl);
 if(!libPromise)libPromise=new Promise((resolve,reject)=>{
  let script=document.getElementById('maplibre-lib');
  if(!script){script=document.createElement('script');script.id='maplibre-lib';script.src='/assets/maplibre-gl.js';document.head.append(script)}
  const clean=()=>{clearTimeout(timeout);script.removeEventListener('load',loaded);script.removeEventListener('error',failed)};
  const failed=()=>{clean();libPromise=null;script.remove();reject(Error('La mappa non si è caricata.'))};
  const loaded=()=>{if(!window.maplibregl)return failed();clean();resolve(window.maplibregl)};
  const timeout=setTimeout(failed,15000);
  script.addEventListener('load',loaded,{once:true});script.addEventListener('error',failed,{once:true});
 });
 return libPromise;
}
export function waitForMap(map,signal){return new Promise((resolve,reject)=>{
 const clean=()=>{clearTimeout(timer);map.off('load',loaded);signal.removeEventListener('abort',aborted)};
 const loaded=()=>{clean();resolve()};
 const aborted=()=>{clean();reject(new DOMException('Navigazione cambiata','AbortError'))};
 const timer=setTimeout(()=>{clean();reject(Error('La cartografia non risponde.'))},15000);
 map.on('load',loaded);signal.addEventListener('abort',aborted,{once:true});if(signal.aborted)aborted();
})}
export function createLocalMap(ctx){
 let map,lib,weather,controller,revision=0,rows=[],pins=new Map(),refreshTimer,flightTimer,storyTimer,story=null,position=null;
 const status=text=>{if($('#local-map-status'))$('#local-map-status').textContent=text};
 const center=()=>[ctx.get().place.longitude,ctx.get().place.latitude];
 function page(){return `<section class="local-map-shell" aria-label="Mappa del meteo e delle persone"><div class="map-skeleton" id="map-skeleton" aria-hidden="true"><div class="map-skeleton-grid"></div>${zoneOutline(ctx.get().place)}</div><div id="local-map-canvas" aria-label="Mappa interattiva della zona"></div><div class="local-map-top"><a href="#tendenze" class="local-map-now" id="local-map-now">${now()}</a><div class="local-map-chips" role="group" aria-label="Livelli della mappa">${[['rain','🌧','Pioggia'],['wind','〰','Vento'],['temperature','°','Temperatura']].map(([id,icon,name])=>`<button type="button" data-map-layer="${id}" aria-pressed="false" disabled><span aria-hidden="true">${icon}</span> ${name}</button>`).join('')}</div><div class="local-map-tools"><button data-map-locate aria-label="Centra sulla mia posizione">⌖</button></div></div><details class="map-sources"><summary aria-label="Fonti e attribuzioni">i</summary><div><p>© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> · <a href="https://openfreemap.org" target="_blank" rel="noopener">OpenFreeMap</a> · <a href="https://maplibre.org" target="_blank" rel="noopener">MapLibre</a></p><p>Radar: <a href="https://www.rainviewer.com" target="_blank" rel="noopener">RainViewer</a>. Il chip senza pioggia richiede immagini recenti e copertura nell’intera area visibile.</p><p>Vento e temperatura: <a href="https://open-meteo.com" target="_blank" rel="noopener">Open-Meteo</a>, dati del modello interpolati. Le scie non sono traiettorie osservate.</p><p>Persone: ultime 2 ore, posizione approssimata.</p></div></details><div class="local-map-bottom"><div id="local-map-legend" hidden></div><p id="local-rain-empty" role="status" hidden>☀️ Nessuna pioggia qui intorno</p><p id="local-map-status" role="status">Apro la tua zona…</p><div id="local-map-weather-note" aria-live="polite"></div><div id="local-radar-controls" hidden><button data-radar-play aria-label="Riproduci radar">▶</button><input type="range" data-radar-range min="0" max="0" value="0" aria-label="Ora delle immagini radar"><output data-radar-time></output></div><button class="sky-camera-button" data-sky-camera>📸 Il tuo cielo</button></div><input type="file" id="sky-camera-input" accept="image/*" capture="environment" hidden><button class="map-opening" id="map-opening" hidden aria-label="Salta introduzione">${esc(ctx.get().place.name)}<span>Tocca per entrare</span></button></section>`}
 function now(){const {weather}=ctx.get(),c=weather?.current;return `${c?`${valueText(c.temperature_2m,'°')} · ${esc(weatherName(c.weather_code))}`:'Il meteo della zona'}<small>${esc(forecastStamp(weather))}</small>`}
 function finishFlight(){clearTimeout(flightTimer);if(!map)return;map.stop();map.jumpTo({center:center(),zoom:11,pitch:0,bearing:0});const intro=$('#map-opening');if(intro)intro.hidden=true;map.setMinZoom(3);markIntro()}
 function geo(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(Error('Posizione non disponibile. Scegli la città in alto.'));navigator.geolocation.getCurrentPosition(p=>resolve({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy}),()=>reject(Error('Posizione non disponibile. Puoi scegliere la città in alto.')),{enableHighAccuracy:true,timeout:12000,maximumAge:30000})})}
 async function bind(){if(ctx.get().route!=='mappa')return;const host=$('#local-map-canvas'),token=++revision;controller=new AbortController();const signal=controller.signal;
 $('#sky-camera-input').onchange=async e=>{const f=e.target.files?.[0];e.target.value='';if(f){try{const {openPostcard}=await import('./sky-postcard.js');await openPostcard(f,ctx)}catch(e){ctx.toast(e.message||'Fotocamera non disponibile.')}}};
 $('[data-sky-camera]').onclick=()=>$('#sky-camera-input').click();
 $('[data-map-locate]').onclick=async()=>{try{position=await geo();if(token!==revision)return;ctx.choose({...position,name:'La mia zona',source:'gps'});status('Posizione aggiornata.')}catch(e){status(e.message)}};

 try{lib=await library();if(token!==revision||!host.isConnected)return;const intro=!introSeen()&&!motion();map=new lib.Map({container:host,style:'https://tiles.openfreemap.org/styles/dark',center:center(),zoom:intro?4:11,maxZoom:18,minZoom:3,pitch:0,attributionControl:false,canvasContextAttributes:{preserveDrawingBuffer:true}});
 map.dragRotate.disable();map.touchZoomRotate.disableRotation();map.addControl(new lib.NavigationControl({showCompass:false}),'bottom-right');
 map.on('error',e=>{if(e.error?.message?.includes('WebGL'))status('Questo dispositivo non supporta la mappa. Apri Meteo o Community.');else if(e.sourceId?.startsWith('radar-'))weather?.radarError();else if(!map.isStyleLoaded())status('Cartografia in caricamento. Controlla la connessione.')});
 await waitForMap(map,signal);if(token!==revision)return;$('#map-skeleton')?.remove();status('');map.addSource('people',{type:'geojson',data:features(),cluster:true,clusterRadius:58,clusterMaxZoom:14});map.addLayer({id:'people-query',type:'circle',source:'people',paint:{'circle-radius':1,'circle-opacity':0}});updatePins();map.on('moveend',()=>{updatePins();weather?.viewChanged()});map.on('sourcedata',e=>{if(e.sourceId==='people'&&map.isSourceLoaded('people'))updatePins()});
 if(intro){markIntro();const overlay=$('#map-opening');overlay.hidden=false;overlay.onclick=finishFlight;map.flyTo({center:center(),zoom:11,duration:1500,essential:false});flightTimer=setTimeout(finishFlight,1550)}else{markIntro()}
 try{const {createMapWeather}=await import('./local-map-weather.js');if(token!==revision)return;weather=createMapWeather(map,ctx,status);document.querySelectorAll('[data-map-layer]').forEach(b=>b.disabled=false)}catch{if(token===revision)status('Livelli meteo non disponibili. La mappa resta utilizzabile.')}
 document.addEventListener('visibilitychange',()=>{weather?.visibility();if(document.hidden&&$('#map-opening')&&!$('#map-opening').hidden)finishFlight()},{signal});
 refreshTimer=setInterval(()=>{if(!document.hidden){paintPeople();updatePins();if(story)showStory(story,false)}},60000);
 }catch(e){if(token!==revision)return;console.error('Local map unavailable:',e);map?.remove();map=null;$('#map-skeleton')?.remove();document.querySelectorAll('[data-map-layer]').forEach(b=>b.disabled=true);host.innerHTML='<div class="map-fallback"><h1>La mappa non è disponibile qui</h1><p>Puoi comunque vedere il meteo e le persone della zona.</p><a class="button" href="#tendenze">Meteo</a><a class="button" href="#community">Community</a><button data-map-retry>Riprova</button></div>';host.querySelector('[data-map-retry]').onclick=()=>{dispose();bind()};status('')}
 }
 function features(){return {type:'FeatureCollection',features:activeReports(rows).map(r=>({type:'Feature',geometry:{type:'Point',coordinates:[r.longitude,r.latitude]},properties:{id:r.id}}))}}
 function paintPeople(){map?.getSource('people')?.setData(features())}
 function updatePins(){if(!map?.getSource('people'))return;const seen=new Set();for(const f of map.querySourceFeatures('people')){const cluster=!!f.properties.cluster,key=cluster?'c'+f.properties.cluster_id:f.properties.id;if(seen.has(key))continue;seen.add(key);let pin=pins.get(key);if(!pin){const button=document.createElement('button');button.type='button';button.className='people-map-pin';pin={button,marker:new lib.Marker({element:button,anchor:'bottom'}).setLngLat(f.geometry.coordinates).addTo(map)}}const {button}=pin;if(cluster){button.innerHTML=`<span>${Number(f.properties.point_count)}</span>`;button.setAttribute('aria-label',`${f.properties.point_count} segnalazioni. Ingrandisci`);button.onclick=async()=>{const source=map?.getSource('people');if(!source)return;try{const zoom=await source.getClusterExpansionZoom(f.properties.cluster_id);map?.easeTo({center:f.geometry.coordinates,zoom,duration:motion()?0:400})}catch{}}}else{const r=rows.find(r=>r.id===key);if(!r)continue;const age=Math.max(0,Math.floor((Date.now()-r.created)/60000));button.innerHTML=`<span>${r.photo?`<img src="/api/sky/photo/${encodeURIComponent(r.id)}" alt="" loading="lazy">`:reportEmoji(r)}</span><small>${age} min</small>`;button.setAttribute('aria-label',`${r.city}, ${reportTitle(r)}, ${age} minuti fa`);button.onclick=()=>showStory(r)}pin.marker.setLngLat(f.geometry.coordinates);pins.set(key,pin)}for(const [key,pin] of pins)if(!seen.has(key)){pin.marker.remove();pins.delete(key)}}
 function closeStory(){story=null;clearTimeout(storyTimer);const d=$('#map-story');d?.close();d?.remove()}
 function showStory(r,fresh=true){if(r.expires<=Date.now()){closeStory();ctx.toast('Questa segnalazione è scaduta.');return}story=r;let d=$('#map-story');if(!d){d=document.createElement('dialog');d.id='map-story';d.className='map-story';d.setAttribute('aria-label','Il cielo raccontato dalle persone');document.body.append(d);d.addEventListener('cancel',closeStory);d.addEventListener('close',()=>{if(story)closeStory()})}if(!fresh&&d.querySelector('[data-story-confirm]')?.disabled)return;const minutes=Math.floor((Date.now()-r.created)/60000),origin=position||(ctx.get().place.source==='gps'?ctx.get().place:null),distance=distanceKm(origin||ctx.get().place,r);d.innerHTML=`<div class="story-progress"><span style="width:${Math.max(0,(r.expires-Date.now())/7200000*100)}%"></span></div><button class="story-close" aria-label="Chiudi storia">×</button>${r.photo?`<img class="story-photo" src="/api/sky/photo/${encodeURIComponent(r.id)}" alt="Il cielo di ${esc(r.city)}">`:`<div class="story-symbol weather-${esc(r.kind)}" aria-hidden="true"><span>${reportEmoji(r)}</span><i></i><i></i><i></i><i></i><i></i></div>`}<div class="story-content"><p>${esc(r.name||'Una voce della zona')}${professionLabel(r.mestiere)} · ${minutes} min fa</p><h1>${esc(reportTitle(r))}</h1><p>${esc(r.city)} · ${origin?(distance<1?'vicino a te':'a '+Math.round(distance)+' km da te'):'a '+(distance<1?distance.toFixed(1):Math.round(distance))+' km dalla città selezionata'}</p>${r.note?`<p>${esc(r.note)}</p>`:''}<p class="story-confirm-count">${r.confirms||0} conferme</p>${!r.own&&r.visibility!=='only-you'&&(!origin||distance<=5)?`<button class="sky-primary" data-story-confirm ${r.confirmed?'disabled':''}>${r.confirmed?'Hai confermato':'✓ Confermo anche io'}</button>`:''}<div class="story-minor">${!r.own?'<button data-story-flag>Segnala abuso</button><button data-story-block>Blocca</button>':'<button data-story-delete>Elimina</button>'}<button data-story-details>Dettagli</button></div><p class="story-status" role="status"></p></div>`;d.querySelector('.story-close').onclick=closeStory;d.querySelector('[data-story-details]').onclick=()=>{closeStory();ctx.showZone(r)};
 d.querySelector('[data-story-confirm]')?.addEventListener('click',async e=>{const b=e.currentTarget;b.disabled=true;try{position=await geo();if(distanceKm(position,r)>5)throw Error('Puoi confermare solo entro 5 km.');if(position.accuracy>2000)throw Error('Posizione poco precisa. Riprova.');await ctx.api('sky/session',{});const result=await ctx.api('sky/reports/'+encodeURIComponent(r.id)+'/confirm',{...position,consent:true});r.confirms=result.confirms;r.confirmed=result.confirmed;try{if(e.isTrusted&&!motion())navigator.vibrate?.(12)}catch{}showStory(r)}catch(err){if(d.isConnected)d.querySelector('.story-status').textContent=err.message}finally{if(b.isConnected)b.disabled=false}});
 const moderate=async type=>{try{await ctx.api('sky/session',{});await ctx.api('sky/'+type,type==='flag'?{id:r.id,reason:'Contenuto da verificare'}:{target:r.author});rows=rows.filter(x=>x.author!==r.author);paintPeople();closeStory();window.dispatchEvent(new Event('sky-published'));ctx.toast('Contenuto nascosto.')}catch(e){d.querySelector('.story-status').textContent=e.message}};
 d.querySelector('[data-story-delete]')?.addEventListener('click',async e=>{const b=e.currentTarget;if(b.dataset.ready!=='1'){b.dataset.ready='1';b.textContent='Conferma eliminazione';return}b.disabled=true;try{await ctx.api('sky/delete',{id:r.id});rows=rows.filter(x=>x.id!==r.id);paintPeople();closeStory();window.dispatchEvent(new Event('sky-published'));ctx.toast('Segnalazione eliminata.')}catch(error){d.querySelector('.story-status').textContent=error.message;b.disabled=false}});
 d.querySelector('[data-story-flag]')?.addEventListener('click',()=>moderate('flag'));d.querySelector('[data-story-block]')?.addEventListener('click',()=>moderate('block'));if(!d.open)d.showModal();clearTimeout(storyTimer);storyTimer=setTimeout(closeStory,Math.max(1,r.expires-Date.now()));}
 function dispose(){revision++;controller?.abort();clearInterval(refreshTimer);clearTimeout(flightTimer);weather?.dispose();weather=null;for(const p of pins.values())p.marker.remove();pins.clear();map?.remove();map=null;closeStory()}
 return {page,bind,dispose,active:()=>ctx.get().route==='mappa',scene:()=>map?{capture:()=>map.getCanvas()}:null,setData(data){rows=data.reports||[];if(data.nearbyReports)rows=[...new Map([...rows,...data.nearbyReports].map(r=>[r.id,r])).values()];paintPeople()},setError:status,refreshWeather(){const n=$('#local-map-now');if(n)n.innerHTML=now();weather?.refreshCity()},updatePlace(){finishFlight();this.refreshWeather();weather?.viewChanged()},celebrate(report){rows=[report,...rows.filter(r=>r.id!==report.id)];paintPeople();map?.easeTo({center:[report.longitude,report.latitude],zoom:12,duration:motion()?0:500});ctx.toast('Il tuo cielo è sulla mappa.')}};
}
